import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

// issue #12: the customer's discount is applied exactly once.
test('customer discount 0.1 on a 1,000 cart under 10 lines is 900', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

// n cart lines of one unit each.
const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

test('10 lines: customer discount, then the 5% bulk discount once (10,000 -> 8,550)', () => {
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('9 lines: customer discount only, no bulk discount (9,000 -> 8,100)', () => {
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

test('discounted total is rounded once to a whole amount (999 at 0.1 -> 899)', () => {
  assert.equal(total([{ price: 999, qty: 1 }], 0.1), 899);
});

test('discount rate 0 leaves totals unchanged (bulk 5% only from 10 lines)', () => {
  assert.equal(total(lines(10, 1000), 0), 9500);
  assert.equal(total(lines(9, 1000), 0), 9000);
});
